import {goTo, note} from 'play';

export default async function main() {
  const MAX_RETRIES = 5;

  let backoff = 1; // seconds
  let last: Awaited<ReturnType<typeof goTo>> | undefined;

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    last = await goTo('sol_belt');

    if (last.status === 'done') {
      return last;
    }

    // A refused trip is a real precondition failure — not transient. Stop at once.
    if (last.status === 'refused') {
      return last;
    }

    // failed (broke mid-way, or the reply was lost) — retry with exponential backoff.
    if (attempt < MAX_RETRIES) {
      note(`sol_belt trip failed on attempt ${attempt + 1}; retrying in ${backoff}s`);
      await new Promise((resolve) => setTimeout(resolve, backoff * 1000));
      backoff *= 2;
    }
  }

  return last!;
}
