import {orient, scout, gatherUntil, prices, sell, note, Outcome} from 'play';

export default async function main() {
  const look = await orient();

  // The task already names the belt and its dock, so a belt check is optional; keep it
  // only to name the belt we are working, since one system may lack it.
  const here = await scout();
  const belt = here.detail.pois.find(p => p.id === 'unknown_edge_mineral_fields');
  if (!belt) {
    note('unknown_edge_mineral_fields is not in this system; returning the scout');
    return here;
  }

  // One loop: 1–4 trips until the store holds 200 iron_ore, or 4 trips of any kind.
  const run = await gatherUntil({
    poi: 'unknown_edge_mineral_fields',
    base: 'frontier_station',
    until: {item: 'iron_ore', quantity: 200},
    maxTrips: 4,
  });

  if (run.status === 'refused') {
    note(`gatherUntil was refused: ${run.why ?? 'no reason given'}`);
    return run;
  }

  // The trips stow at the base, so `run.now.cargo` is empty: the take is `run.gained.items`
  // (measured aboard) and `run.detail.settled` (what reached the store, ready to sell).
  note(`settled ${run.detail?.settled?.map(r => `${r.quantity} ${r.item_id}`).join(', ') || 'nothing'}`);

  const take = run.detail?.settled ?? [];
  const cheap = take.filter(r => r.item_id !== 'iron_ore');
  if (!cheap.length) {
    note('nothing besides iron_ore settled; nothing to sell from the store');
    return run;
  }

  // A floor guards against a 0-price quote of a row that actually names a buyer elsewhere.
  return sell(cheap, {from: 'store'});
}
