import {orient, salvage, goTo, sell, note, outcome, type Outcome, type Want} from 'play';

export default async function main() {
  const here = await orient();
  if (here.now?.location?.poi_id !== 'sol_debris') {
    return outcome(`salvage refused: not at sol_debris (we are at ${here.now?.location?.poi_id ?? 'nowhere'})`, {status: 'refused'});
  }

  const first = await salvage();

  // No wreck, or a hold that cannot take it: this is the end.
  if (first.status === 'refused') {
    note('no wreck — ' + (first.why ?? 'salvage refused'));
    return first;
  }

  // The hold filled mid-salvage, or is at a level where the next trip cannot land the rest:
  // take it in, sell it all, come back, salvage again.
  if (first.status === 'partial' || first.now.cargo.length > 0) {
    const took: Want[] = first.gained.items.map(row => ({item_id: row.item_id, quantity: row.quantity}));
    if (took.length) {
      const goIn = await goTo('sol_station');
      if (goIn.status !== 'done') return goIn;
      const sold = await sell(took, {from: 'hold'});
      if (sold.status !== 'done' && sold.status !== 'partial') return sold;

      const goBack = await goTo('sol_debris');
      if (goBack.status !== 'done') return goBack;
    }

    const second = await salvage();
    if (second.status === 'refused') {
      note('no wreck — ' + (second.why ?? 'salvage refused'));
      return second;
    }
    return second; // the last Outcome
  }

  // done with a clean hold, or partial for any other reason (fuel, hull): this is the end.
  return first;
}
