import {orient, prices, missions, note} from 'play';

function isRecordValue(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function getRecordValue(value: unknown, key: string): unknown {
  if (!isRecordValue(value)) return undefined;
  return value[key];
}

function rowsFrom(value: unknown): Record<string, unknown>[] {
  if (Array.isArray(value)) {
    return value.filter((item): item is Record<string, unknown> => isRecordValue(item));
  }
  if (isRecordValue(value)) {
    return Object.values(value).filter((item): item is Record<string, unknown> => isRecordValue(item));
  }
  return [];
}

function numericValue(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function countMissions(detail: unknown): number {
  if (typeof detail === 'number' && Number.isFinite(detail)) return Math.max(0, detail);

  const asArray = Array.isArray(detail) ? detail : null;
  if (asArray) return asArray.length;

  if (!isRecordValue(detail)) return 0;

  const boardKeys = [
    'missions',
    'board',
    'list',
    'items',
    'available',
    'offers',
    'requests',
    'active',
    'available_missions',
    'open',
    'all',
  ];

  for (const key of ['count', 'total', 'length', 'num_missions', 'mission_count']) {
    const n = numericValue(detail[key]);
    if (n !== null && n >= 0) return n;
  }

  for (const key of boardKeys) {
    const v = detail[key];

    if (Array.isArray(v)) return v.length;

    if (isRecordValue(v)) {
      const nestedArrays = Object.values(v).filter((item): item is unknown[] => Array.isArray(item));
      if (nestedArrays.length > 0) {
        const total = nestedArrays.reduce((sum, arr) => sum + arr.length, 0);
        if (total > 0) return total;
      }

      const keys = Object.keys(v);
      if (
        keys.length > 0 &&
        keys.every((k) => /mission|id/i.test(k))
      ) {
        return keys.length;
      }
    }
  }

  const missionLikeKeys = ['mission_id', 'id', 'title', 'name', 'brief', 'payload', 'reward', 'xp', 'credits'];
  const values = Object.values(detail);
  let missionLike = 0;
  for (const v of values) {
    if (Array.isArray(v)) {
      for (const item of v) {
        if (isRecordValue(item) && Object.keys(item).some((k) => missionLikeKeys.includes(k))) {
          missionLike += 1;
        }
      }
    } else if (isRecordValue(v)) {
      if (Object.keys(v).some((k) => missionLikeKeys.includes(k))) {
        missionLike += 1;
      }
    }
  }
  if (missionLike > 0) return missionLike;

  let json = '';
  try {
    json = JSON.stringify(detail) ?? '';
  } catch {
    json = '';
  }
  const matches = json.match(/"mission_id"\s*:/g);
  return matches ? matches.length : 0;
