      // Not done: return the trip, and always end by noting current credits.
      const last = await orient();
      note(`credits: ${last.now?.credits ?? 0}`);
      return trip;
    }

    // Sell the copper_ore that trip settled, from the store. A trip that stows ends with
    // an empty hold, so read the take from detail.settled (Row: item_id + quantity).
    const cu = (trip.detail.settled ?? []).filter((r) => r.item_id === 'copper_ore');
    if (cu.length) {
      out = await sell(cu, { from: 'store' });
