    // Whatever the steps above did or threw, end by noting current credits from orient().
    const last = await orient();
    note(`credits: ${last.now?.credits ?? 0}`);

    return sv; // the service Outcome
  } catch {
    // Even if a step threw, the last thing the program does is note current credits.
    try {
      const last = await orient();
      note(`credits: ${last.now?.credits ?? 0}`);
    } catch {
      // orient itself failed; record the failure rather than crash out of main.
      await note('failed: could not read current credits after an error');
    }
    return out; // return the last successful Outcome
  }
}
