import {orient, goTo, salvage, sell, note, type Outcome} from 'play';

export default async function main() {
  const start = await orient();
  const here = start.detail.present.location.poi_id;
  if (here !== 'sol_debris') note(`expected sol_debris, at ${here ?? 'nowhere'}`);

  const first = await salvage();

