  if (first.status === 'partial') {
    const reason = first.why ?? '';
    const holdFilled = /hold|room|full|space|cargo/i.test(reason);
    if (!holdFilled) {
      note(`partial for another reason: ${reason}; returning as-is`);
      return first;
