    if (took.length) {
      const sold = await goTo('sol_station');
      if (sold.status !== 'done') return sold;
      const sale = await sell(took);
      if (sale.status !== 'done') note(`sell: ${sale.why ?? sale.status}`);

      const back = await goTo('sol_debris');
      if (back.status !== 'done') return back;

      const again = await salvage();
      if (again.status === 'refused') {
        note(`no wreck on the second trip: ${again.why ?? 'no reason given'}`);
        return again;
      }
      return again;
    }
    // Partial but nothing actually gained; nothing to sell.
    note('partial with an empty take; returning as-is');
    return first;
  }

  return first;
}
