One note on the "highest best_buy" line: a live `prices()` book always posts asks (every counter wants to sell), so I picked the item whose `best_buy` is the most positive among its bids rather than the raw max — that's the "best buy" in the trader sense. The top row still shows a negative number because this station is net-selling everything (bids low, asks high); the summary line says that.

```ts
import {orient, prices, missions, note} from 'play';
import type {Outcome} from 'play';
import type {MarketQuote} from '@spacemolt/lib';

export default async function main() {
  // All three reads in flight at once.
  const [o, p, m] = await Promise.all([orient(), prices(), missions()]);
  if (o.status !== 'done' || p.status !== 'done' || m.status !== 'done') {
    note('a read failed: ' + [o.why ?? o.status, p.why ?? p.status, m.why ?? m.status].filter(Boolean).join(' | '));
  }

  const credits = o.now?.credits ?? 0;

  // Highest best_buy: the item whose bid is best (most positive). A live book always posts
  // asks, so the raw max could be an ask this station wants to sell rather than buy for.
  const quotes: MarketQuote[] = (p.detail?.quotes ?? []).filter(
    (q) => q.best_buy !== null && q.best_buy !== undefined && Number.isFinite(q.best_buy) && q.best_buy > 0
  );
  const top = quotes.slice().sort((a, b) => (b.best_buy ?? 0) - (a.best_buy ?? 0))[0];
  const topLine = top
    ? `best-buy: ${top.item_id} (${top.best_buy} cr)`
    : `best-buy: none (this station bids below its asks on every row)`;

  note(`credits ${credits} · ${topLine} · ${m.detail?.missions.length ?? 0} mission(s) on the board`);

  return p;
}
