import {
  orient,
  missions,
  acceptMission,
  completeMissions,
  note,
  outcome,
  account,
} from 'play';
import type { Outcome } from 'play';
import type { V2Ship, V2CargoItem } from '@spacemolt/lib';

/** Size of one cargo unit. Most goods are 1; some (e.g. osmium) take 2. */
function unitSize(row: V2CargoItem): number {
  const value = (row as unknown as { size?: number }).size ?? 1;
  return Number.isFinite(value) && value > 0 ? value : 1;
}

/** Cargo slots already used by the current hold. */
function usedSlots(
  ship: V2Ship | null | undefined,
  cargo: readonly V2CargoItem[] | null | undefined
): number {
  if (!ship || !Array.isArray(cargo)) return 0;
  const known = cargo.reduce((n, row) => n + row.quantity * unitSize(row), 0);
  return Math.min(known, (ship as unknown as { max_cargo?: number }).max_cargo ?? Number.MAX_SAFE_INTEGER);
}

/** Free board slots the hold has left. */
function freeSlots(
  ship: V2Ship | null | undefined,
  cargo: readonly V2CargoItem[] | null | undefined
): number {
  const max = (ship as unknown as { max_cargo?: number }).max_cargo;
  return Math.max(0, (Number.isFinite(max) ? max : 0) - usedSlots(ship, cargo));
}

/** A row of the mission board that carries an id, a reward, and its kind. */
interface BoardRow {
  id: string;
  reward: number;
  kind?: string;
}

function isBoardRow(value: unknown): value is BoardRow {
  const row = value as BoardRow | null | undefined;
  return !!row && typeof row.id === 'string' && typeof row.reward === 'number';
}

/** The accepted rows of a board, keyed by id. Empty when the board isn't in the expected shape. */
function boardEntries(missionsDetail: unknown): Record<string, BoardRow> {
  const entries: Record<string, BoardRow> = {};
  if (!missionsDetail || typeof missionsDetail !== 'object') return entries;
  const board = (missionsDetail as { board?: unknown }).board;
  if (!Array.isArray(board)) return entries;
  for (const value of board) if (isBoardRow(value)) entries[value.id] = value;
  return entries;
}

export default async function main() {
  const here = await orient();

  const currentSlots = freeSlots(here.now?.ship, here.now?.cargo);
  let free = currentSlots;
  let accepted = 0;

  const board = await missions();

  if (board.status !== 'done') {
    return outcome(`list of missions not available at ${here.now?.location?.poi_name ?? 'here'}`, {
      status: 'partial',
      detail: { accepted: 0, why: board.why ?? board.did ?? 'mission board unreadable' },
    });
  }

  // Every board row paying >= 100, highest reward first (deterministic, so we take the best).
  const entries = boardEntries(board.detail);
  const picks = Object.values(entries)
    .filter((row) => row.reward >= 100)
    .sort((a, b) => b.reward - a.reward || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  // Read the live hold once, for a slot check that reflects any cargo still aboard.
  const liveShip: V2Ship | null = account().ship ?? null;
  const liveCargo = account().cargo ?? [];

  for (const row of picks) {
    if (free <= 0) break; // no more slots for missions
    const res = await acceptMission(row.id);
    if (res.status !== 'done') break; // stop at the first accept that did not land
    accepted += 1;
    free -= 1;
  }

  const completed = await completeMissions();
  if (completed.status !== 'done') note(`completeMissions not done: ${completed.why ?? completed.did}`);

  // Reconcile slots against what the game reports after the run of accepts, so the detail is honest.
  const afterSlots = freeSlots(liveShip, liveCargo);
  const totalPicks = picks.length;
  const eligible = totalPicks;

  note(
    `accepted ${accepted} of ${eligible} board mission(s) (>= 100 reward); slots left: ${afterSlots}`
  );

  return outcome(
    `listed the board at ${here.now?.location?.poi_name ?? 'here'} and accepted ${accepted} mission(s) (>= 100 reward, no more than ${currentSlots} free slot(s) allow)`,
    { status: completed.status, detail: { accepted } }
  );
}
